insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-15-foundation-free-body-diagrams',15,'Day 15 · Foundation: Free-body diagrams',array['u1.draw-fbd'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-15','day-15-foundation-free-body-diagrams','day-15-force-diagrams',array['f15-book','f15-release','f15-ball','f15-turn','f15-exit'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-3a','r2-3b','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 15 · Quiz: Free-body diagrams","instructions":"Work on your own. Choose one object and name the source of every force.","questions":[{"kind":"choice","points":1,"prompt":"A lamp hangs at rest from a vertical cord. Which forces belong on the lamp’s diagram?","options":["Cord tension up and weight down","Lamp on cord and weight","Weight only","Weight, tension and a net-force arrow"],"correct_index":0,"guide":"The cord pulls up and Earth pulls down on the lamp.","demand":{"blooms":"Understand","dok":1,"evidence":"Chooses forces on the named object."}},{"kind":"choice","points":1,"prompt":"A crate slides left across a rough level floor after a hand lets go. Which horizontal force remains?","options":["Hand force left","Sliding friction right","Motion force left","Weight right"],"correct_index":1,"guide":"Sliding friction opposes the crate’s slip. The hand no longer touches the crate.","demand":{"blooms":"Apply","dok":2,"evidence":"Identifies an active interaction after release."}},{"kind":"written","points":3,"prompt":"A ball rises after leaving a hand. Ignore air resistance. Describe its force diagram while rising and at the very top. Explain why the arrows stay or change.","guide":"In both cases Earth pulls down. Near the surface its weight is effectively constant. No force from the hand remains. Zero vertical velocity at the top does not remove gravity.","demand":{"blooms":"Analyze","dok":2,"evidence":"Separates force from instantaneous velocity."}},{"kind":"written","points":3,"prompt":"A rope pulls a box right with 15 N while friction acts left with 5 N. Support and weight balance. Describe the four arrows and explain why the net force is not a fifth arrow.","guide":"Tension right, friction left, support up and weight down. The vertical arrows match. The right arrow is three times the left. The net force of 10 N right summarizes the forces already drawn.","demand":{"blooms":"Analyze","dok":2,"evidence":"Checks direction, source and relative length."}}]}'::jsonb);
